mapper.select:
SELECT id, playlist_id AS playlistId, song_id AS songId,
       position, added_at AS addedAt
FROM playlist_track
WHERE playlist_id = #{playlistId}
ORDER BY position
LIMIT #{limit}

SELECT id, playlist_id AS playlistId, song_id AS songId,
       position, added_at AS addedAt
FROM (
    SELECT pt.*,
           ROW_NUMBER() OVER (PARTITION BY pt.playlist_id ORDER BY pt.position) AS rn
    FROM playlist_track pt
    WHERE pt.playlist_id IN
    #{pid}
) sub
WHERE sub.rn <= #{limit}
